    msg = struct.pack(">HHHHHH", tid, 0x0100, 1, 0, 0, 0)
    msg += b"".join(bytes([len(p)]) + p.encode() for p in qname.split(".")) + b"\x00"
    msg += struct.pack(">HH", 1, 1)
